import { catchAsync } from "utils/catchAsync";
import { requestService } from "../../services";
import httpStatus from "http-status";

export const fetchAllFriends = catchAsync(async (req, res) => {
  // get friends
  const { userId } = req.query;
  if (!userId) {
    res.status(httpStatus.BAD_REQUEST).send({
      success: false,
      message: "You need to send user id",
    });
  }
  const allFriends = await requestService.getAllfriends(userId);
  if (allFriends === null) {
    res.status(httpStatus.OK).send({
      success: true,
      message: "There is no friend for this user",
      data: allFriends,
    });
  } else {
    res.status(httpStatus.OK).send({
      success: true,
      message: "Friends are fetched successfully",
      data: allFriends,
    });
  }
});

export const sendFriendRequest = catchAsync(async (req, res) => {
  // send friend request logic here
  const { from, to } = req.body;
  if (!from || !to) {
    res.status(httpStatus.BAD_REQUEST).send({
      success: false,
      message: "You need to send proper data for from and to user id",
    });
  }
  if (from === to) {
    res.status(httpStatus.BAD_REQUEST).send({
      success: false,
      message: "You can not send the request to your self ",
    });
  }
  const request = await requestService.createRequest({ from, to });
  res.status(httpStatus.OK).send({
    success: true,
    message: "Request is send successfully",
    data: request,
  });
});

